import{_ as t,o as r,c as e,a2 as o}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"社区使用","description":"板块、发帖、回帖、审核与私信交流指南。","frontmatter":{"title":"社区使用","description":"板块、发帖、回帖、审核与私信交流指南。","order":40,"group":"community"},"headers":[],"relativePath":"community-guide.md","filePath":"community-guide.md"}'),n={name:"community-guide.md"};function i(l,a,s,u,d,c){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="社区使用指南" tabindex="-1">社区使用指南 <a class="header-anchor" href="#社区使用指南" aria-label="Permalink to &quot;社区使用指南&quot;">​</a></h1><p>MetaFusion 社区遵循“浏览开放、互动需登录”的原则，为爱好者与考据者提供开放、友好的交流空间。</p><h2 id="社区板块" tabindex="-1">社区板块 <a class="header-anchor" href="#社区板块" aria-label="Permalink to &quot;社区板块&quot;">​</a></h2><p>社区默认划分为三大核心讨论区：</p><ul><li><strong>公告（Announcement）</strong>：站务通知、版本更新与重要规则发布（仅站务团队可发布）。</li><li><strong>综合讨论（General）</strong>：作品交流、版本考据、创作心得与日常探讨。</li><li><strong>评注分区（Comment）</strong>：针对具体作品或发行版的深度条目评注，默认不占用全站综合信息流。</li></ul><p>在社区首页，你可以通过顶部的语种切换器筛选特定语言的讨论内容（如简体中文、英语等）。</p><h2 id="浏览与发帖" tabindex="-1">浏览与发帖 <a class="header-anchor" href="#浏览与发帖" aria-label="Permalink to &quot;浏览与发帖&quot;">​</a></h2><ul><li><strong>浏览与检索</strong>：游客及所有注册用户均可在社区大厅按板块浏览讨论主题，或在顶部搜索栏输入关键词检索历史讨论。</li><li><strong>发起新话题</strong>：登录后，在社区页面点击「发布话题」，选择所属板块并填写标题与正文（支持 Markdown 语法排版）。发布时可关联对应的作品生成信息卡片，并可添加专属话题标签。</li><li><strong>参与回复</strong>：进入任意话题详情页，即可阅读完整楼层对话。在页面底部输入框中撰写回复，支持引用特定楼层进行精准探讨。</li></ul><h2 id="站内私信" tabindex="-1">站内私信 <a class="header-anchor" href="#站内私信" aria-label="Permalink to &quot;站内私信&quot;">​</a></h2><p>登录用户可在任意用户的个人主页点击「发送私信」，或在私信收件箱中发起一对一即时交流，适合进行私下协作考据、文献补充与站务问题沟通。</p><h2 id="社区规范与审核" tabindex="-1">社区规范与审核 <a class="header-anchor" href="#社区规范与审核" aria-label="Permalink to &quot;社区规范与审核&quot;">​</a></h2><ul><li><strong>内容合规</strong>：社区配有巡查与审核机制，严禁发布侵权盗版链接、商业广告、恶意灌水与人身攻击内容。违规内容将被清理，违规账号将被限制互动或封禁。</li><li><strong>频率保护</strong>：为了维护良好的交流秩序，短时间内连续高频发帖或私信会触发系统的频率保护。</li></ul><h2 id="快速入口" tabindex="-1">快速入口 <a class="header-anchor" href="#快速入口" aria-label="Permalink to &quot;快速入口&quot;">​</a></h2><ul><li><strong>导航入口</strong>：点击顶部导航栏的 <strong>“社区”</strong> 即可进入板块广场与最新动态流。</li><li><strong>关联引用</strong>：在讨论作品时，建议在发帖界面关联对应作品，系统将自动生成精美信息卡片，方便其他同好快速跳转查阅。</li></ul>',14)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
